output_text:
[
  {
    "id": "no_carts_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_only_on_foot",
    "text": "A shopper may enter a single-file shelf aisle only after letting go of the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "shelf_service_correct_cart_mode",
    "text": "Shelf interactions in cart-accessible aisles require a cart, while shelf interactions in single-file pedestrian aisles require being without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleShelfCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "INTERACT",
              "cartAccessibleShelfCell",
              {
                "not": "hasCart"
              }
            ]
          },
          {
            "and": [
              "INTERACT",
              "singleFileShelfAisle",
              "hasCart"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "cart_handling_only_at_zones",
    "text": "Carts may be picked up or parked only at the entrance cart corral or at designated aisle-mouth parking bays.",
    "abstraction": {
      "state_properties": {
        "entranceCartCorral": "at(1,7)",
        "pedestrianCartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartHandlingZone": {
          "or": [
            "entranceCartCorral",
            "pedestrianCartBay"
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "cartDrop",
              "cartPickup"
            ]
          },
          {
            "not": "cartHandlingZone"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "Whenever a shopper parks a cart at a pedestrian aisle bay, they are obliged to reclaim a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "pedestrianCartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtPedestrianBay": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "pedestrianCartBay"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartReclaimed": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtPedestrianBay",
      "discharge": "cartReclaimed"
    }
  },
  {
    "id": "no_leave_bay_on_foot_to_general_floor",
    "text": "After parking a cart at an aisle-mouth bay, a cart-free shopper may move only into the pedestrian-only aisle, not out into the general shopping floor.",
    "abstraction": {
      "state_properties": {
        "pedestrianCartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "generalFloor": {
          "and": [
            {
              "not": "singleFileShelfAisle"
            },
            {
              "not": "pedestrianCartBay"
            }
          ]
        }
      },
      "events": {
        "leaveBayOnFootToGeneralFloor": {
          "pre": {
            "and": [
              "pedestrianCartBay",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "generalFloor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveBayOnFootToGeneralFloor"
    }
  },
  {
    "id": "eastbound_one_way_wide_aisles",
    "text": "Wide horizontal aisles are one-way eastbound, so shoppers should not travel west along them.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "wideHorizontalAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_floor_without_cart",
    "text": "A shopper may not leave the entrance area for the shopping floor unless they have taken a cart.",
    "abstraction": {
      "state_properties": {
        "entranceArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "shoppingFloor": {
          "not": "entranceArea"
        }
      },
      "events": {
        "enterShoppingFloorWithoutCart": {
          "pre": {
            "and": [
              "entranceArea",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "shoppingFloor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterShoppingFloorWithoutCart"
    }
  }
]
